SELECT id FROM repairs
WHERE fee IS NOT NULL
ORDER BY fee DESC, id ASC LIMIT 1;

SELECT t.name, COUNT(r.id) AS jobs
FROM techs AS t LEFT JOIN repairs AS r ON r.tech = t.id
WHERE t.name = 'Uma' GROUP BY t.id, t.name;

SELECT t.id FROM techs AS t
WHERE EXISTS (SELECT 1 FROM repairs AS r
  WHERE r.tech = t.id AND r.status = 'done');

SELECT id FROM repairs WHERE status = 'done'
UNION
SELECT id FROM repairs WHERE fee >= 60;

SELECT id, ROW_NUMBER() OVER (
  PARTITION BY tech ORDER BY id) AS position
FROM repairs ORDER BY id;

SELECT site, COUNT(reading) AS n FROM samples
WHERE reading >= 4 GROUP BY site
HAVING COUNT(reading) >= 2;

SELECT id FROM samples WHERE site = 'A'
UNION ALL
SELECT id FROM samples WHERE reading IS NULL;

SELECT id FROM (
  SELECT id, ROW_NUMBER() OVER (
    PARTITION BY site ORDER BY id) AS position
  FROM samples WHERE site IS NOT NULL
) WHERE position = 1;

SELECT id, SUM(reading) OVER (
  ORDER BY day RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
) AS cumulative FROM samples ORDER BY id;

SELECT hub, SUM(weight) AS sent_weight FROM deliveries
WHERE status = 'sent' AND hub IS NOT NULL
GROUP BY hub HAVING SUM(weight) > 10 ORDER BY hub;

SELECT h.code FROM hubs AS h
LEFT JOIN deliveries AS d ON d.hub = h.code
WHERE d.status = 'sent' GROUP BY h.code;

SELECT h.code, d.id FROM hubs AS h
FULL OUTER JOIN deliveries AS d ON d.hub = h.code
WHERE h.code IS NULL OR d.id IS NULL;

SELECT h.code FROM hubs AS h
WHERE NOT EXISTS (SELECT 1 FROM deliveries AS d
  WHERE d.hub = h.code) ORDER BY h.code;
